<?php
require __DIR__.'/common.php';$u=require_user($pdo);check_csrf();$d=json_input();
try{$name=trim((string)($d['fullName']??''));$email=trim((string)($d['email']??''));$phone=trim((string)($d['phone']??''));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))respond(['ok'=>false,'message'=>'Thông tin cá nhân chưa hợp lệ.'],422);$q=$pdo->prepare('SELECT password FROM users WHERE user_id=?');$q->execute([$u['id']]);$hash=(string)$q->fetchColumn();if(!empty($d['password'])){if(strlen((string)$d['password'])<5)respond(['ok'=>false,'message'=>'Mật khẩu phải có ít nhất 5 ký tự.'],422);$hash=password_hash((string)$d['password'],PASSWORD_DEFAULT);}$s=$pdo->prepare('UPDATE users SET password=?,full_name=?,email=?,phone=? WHERE user_id=?');$s->execute([$hash,$name,$email,$phone,$u['id']]);respond(['ok'=>true,'user'=>current_user($pdo),'message'=>'Đã cập nhật thông tin cá nhân.']);}catch(PDOException $e){error_log($e->__toString());respond(['ok'=>false,'message'=>$e->getCode()==='23000'?'Email đã được sử dụng.':'Không thể cập nhật thông tin.'],409);}catch(Throwable $e){error_log($e->__toString());respond(['ok'=>false,'message'=>'Không thể cập nhật thông tin.'],500);}
